"""Differential fuzz: optimized engine vs naive reference."""
import random
import sys
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/tmp')
from crosscheck import Stream
import ref as refmod


def rand_topology(rng):
    n = rng.randint(1, 6)
    ids = list(range(n))
    names = []
    used = set()
    for i in ids:
        while True:
            nm = ''.join(rng.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(rng.randint(1, 4)))
            if nm[0].isalpha() and nm not in used:
                used.add(nm)
                names.append(nm)
                break
    links = set()
    # spanning tree
    order = ids[:]
    rng.shuffle(order)
    for i in range(1, len(order)):
        a, b = order[i], order[rng.randrange(i)]
        links.add((min(a, b), max(a, b)))
    extra = rng.randint(0, 4)
    for _ in range(extra):
        a, b = rng.sample(ids, 2) if n >= 2 else (0, 0)
        if a != b:
            links.add((min(a, b), max(a, b)))
    # degree cap 8
    deg = {}
    keep = []
    for a, b in sorted(links):
        if deg.get(a, 0) < 8 and deg.get(b, 0) < 8:
            keep.append((a, b))
            deg[a] = deg.get(a, 0) + 1
            deg[b] = deg.get(b, 0) + 1
    ext_count = rng.randint(0, min(4, n))
    ext = rng.sample(ids, ext_count) if ext_count else []
    nodes = [{'id': i, 'name': names[i], 'external_capacity': rng.choice([0, 5, 20, 100, 10 ** 9])} for i in ids]
    rng.shuffle(nodes)
    link_spec = [{'source': a, 'target': b, 'capacity': rng.choice([0, 3, 17, 100, 10 ** 9])} for a, b in keep]
    rng.shuffle(link_spec)
    extnames = [names[i] for i in ext]
    rng.shuffle(extnames)
    return {'nodes': nodes, 'links': link_spec, 'external_nodes': extnames}


def all_simple_paths(adj, s, d, limit=40):
    out = []
    stack = [(s, [s])]
    while stack and len(out) < limit:
        node, path = stack.pop()
        if node == d:
            out.append(path[:])
            continue
        for nxt in adj[node]:
            if nxt not in path:
                stack.append((nxt, path + [nxt]))
    return out


def rand_routes(rng, topo):
    names = {n['name'] for n in topo['nodes']}
    id_to_name = {n['id']: n['name'] for n in topo['nodes']}
    name_to_id = {v: k for k, v in id_to_name.items()}
    ext = [name_to_id[x] for x in topo['external_nodes']]
    if len(ext) < 2:
        return {}
    adj = {i: set() for i in id_to_name}
    for l in topo['links']:
        adj[l['source']].add(l['target'])
        adj[l['target']].add(l['source'])
    plan = {}
    for s in ext:
        for d in ext:
            if s == d:
                continue
            paths = all_simple_paths(adj, s, d)
            if not paths:
                return None
            k = rng.randint(1, min(4, len(paths)))
            chosen = rng.sample(paths, k)
            weights = []
            remaining = 1000
            for i in range(k):
                if i == k - 1:
                    weights.append(remaining)
                else:
                    w = rng.randint(1, remaining - (k - i - 1))
                    weights.append(w)
                    remaining -= w
            bundle = [{'path': [id_to_name[x] for x in p], 'weight': w} for p, w in zip(chosen, weights)]
            rng.shuffle(bundle)
            plan.setdefault(id_to_name[s], {})[id_to_name[d]] = bundle
    return plan


def rand_settings(rng):
    return {'trials': rng.randint(1, 6), 'epsilon': rng.choice([0, 0, 1000, 20000, 100000, 250000]),
            'seed': rng.randint(0, 2 ** 32 - 1), 'cutoff': [rng.randint(0, 5 * rng.randint(1, 3)), rng.randint(1, 4)],
            'bias': rng.choice([0, 0, 24000, 1000000]), 'tau': rng.choice([0, 1000, 50000, 1000000]),
            'gamma': [rng.randint(0, 4), rng.randint(1, 3)], 'cache_slots': rng.randint(0, 3)}


def gen_events(rng, topo, settings, n_events):
    id_to_name = {n['id']: n['name'] for n in topo['nodes']}
    name_to_id = {v: k for k, v in id_to_name.items()}
    ext = [name_to_id[x] for x in topo['external_nodes']]
    cap = {}
    for l in topo['links']:
        cap[(l['source'], l['target'])] = l['capacity']
        cap[(l['target'], l['source'])] = l['capacity']
    extcap = {n['id']: n['external_capacity'] for n in topo['nodes']}
    for e in ext:
        cap[(-1, e)] = extcap[e]
        cap[(e, -1)] = extcap[e]
    keys = {}
    for f in sorted(cap):
        a, b = f
        if a == -1:
            keys[f] = ['low_%s_origination' % id_to_name[b]]
        elif b == -1:
            keys[f] = ['low_%s_termination' % id_to_name[a]]
        else:
            keys[f] = ['low_%s_egress_to_%s' % (id_to_name[a], id_to_name[b]),
                       'low_%s_ingress_from_%s' % (id_to_name[b], id_to_name[a])]
    events = []
    repairs = []
    counter = [0]

    def newid(tag):
        counter[0] += 1
        return '%s%d' % (tag, counter[0])

    for _ in range(n_events):
        roll = rng.random()
        if roll < 0.35:
            demands = []
            for _ in range(rng.randint(0, min(4, max(0, len(ext) * (len(ext) - 1))))):
                if len(ext) < 2:
                    break
                s, d = rng.sample(ext, 2)
                if any(x[0] == s and x[1] == d for x in demands):
                    continue
                demands.append([s, d, rng.choice([0, 1, 3, 10, 40, 10 ** 9])])
            cells = {}
            for f in sorted(cap):
                if rng.random() < 0.5:
                    continue
                if rng.random() < 0.2:
                    cells[keys[f][0]] = None
                else:
                    cells[keys[f][0]] = rng.randint(0, cap[f])
                if len(keys[f]) > 1 and rng.random() < 0.5:
                    cells[keys[f][1]] = rng.randint(0, cap[f]) if rng.random() > 0.2 else None
            events.append({'op': 'patch', 'demands': demands, 'counters': cells})
        elif roll < 0.55:
            plan = rand_routes(rng, topo)
            if plan is None:
                plan = None
            events.append({'op': 'routes', 'label': 'L%d' % rng.randint(0, 3), 'paths': plan})
        elif roll < 0.85:
            sid = newid('r')
            repairs.append(sid)
            events.append({'op': 'repair', 'id': sid})
        else:
            if repairs:
                events.append({'op': 'validate', 'id': rng.choice(repairs)})
    return events


def norm(answer):
    import json
    return json.loads(json.dumps(answer, sort_keys=True))


def run_case(topo, settings, events, verbose=False):
    stream = Stream({'topology': topo, 'settings': settings, 'events': events})
    mine = [stream.handle(e) for e in events]
    r = refmod.Ref(topo, settings)
    theirs = []
    for e in events:
        op = e['op']
        if op == 'patch':
            accepted = apply_patch_ref(r, e)
            theirs.append({'op': 'patch', 'accepted': accepted})
        elif op == 'routes':
            apply_routes_ref(r, e)
            theirs.append({'op': 'routes', 'accepted': True})
        elif op == 'repair':
            theirs.append(r.do_repair(e['id']))
        else:
            theirs.append(r.do_validate(e['id']))
    for i, (a, b) in enumerate(zip(mine, theirs)):
        if norm(a) != norm(b):
            print('MISMATCH at event', i, events[i])
            print('mine  ', norm(a))
            print('ref   ', norm(b))
            return False
    return True


def apply_patch_ref(r, ev):
    # reference trusts the generator: all patches are valid
    for s, d, v in ev['demands']:
        r.demands[(s, d)] = v
    for k, cell in ev['counters'].items():
        r.counters[k] = None if cell is None else cell['perturbed']
    return True


def apply_routes_ref(r, ev):
    plan = ev['paths']
    if plan is None:
        r.paths_present = False
        r.paths = {}
        return
    name_to_id = r.name_to_id
    entries = {}
    for sname, bundles in plan.items():
        for dname, opts in bundles.items():
            lst = []
            for o in opts:
                names = o['path']
                hops = tuple((name_to_id[names[i]], name_to_id[names[i + 1]]) for i in range(len(names) - 1))
                lst.append((hops, o['weight']))
            entries[(name_to_id[sname], name_to_id[dname])] = lst
    r.paths = entries
    r.paths_present = True


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    ok = 0
    for i in range(count):
        topo = rand_topology(rng)
        settings = rand_settings(rng)
        events = gen_events(rng, topo, settings, rng.randint(1, 12))
        if run_case(topo, settings, events):
            ok += 1
        else:
            print('case', i, 'topo', topo)
            print('settings', settings)
            print('events', events)
            return 1
    print('all %d cases matched' % ok)
    return 0


if __name__ == '__main__':
    sys.exit(main())
